const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/job-directory.cjs');
const fs=require('node:fs/promises');
const path=require('node:path');
const os=require('node:os');
test('unique immediate children without changing existing files', async () => {
  const root=await fs.mkdtemp(path.join(os.tmpdir(),'job-area-'));
  try {
    const parent=path.join(root,'worker queue'); await fs.mkdir(parent);
    await fs.writeFile(path.join(parent,'keep.txt'),'retain');
    const paths=await Promise.all([
      app.createJobDirectory(parent),app.createJobDirectory(parent),app.createJobDirectory(parent+path.sep)
    ]);
    assert.equal(new Set(paths).size,3);
    for(const created of paths) {
      assert.equal(typeof created,'string'); assert.equal(path.dirname(created),parent);
      assert.ok(path.basename(created).startsWith('job-'));
      assert.ok(path.basename(created).length>4);
      assert.ok((await fs.stat(created)).isDirectory());
    }
    assert.equal(await fs.readFile(path.join(parent,'keep.txt'),'utf8'),'retain');
    assert.deepEqual((await fs.readdir(root)).sort(),['worker queue']);
  } finally { await fs.rm(root,{recursive:true,force:true}); }
});

